-- SEED ms_gestion  (categoria, proveedor, medicamento, lote, factura, recetas)
-- Ejecutar:  psql "<conn ms_gestion>" -f seed_ms_gestion.sql
-- Requiere que Flyway ya haya creado el esquema (levanta ms-gestion antes).
BEGIN;
TRUNCATE detalle_factura, detalle_receta, factura, receta, movimiento_inventario, lote, medicamento, proveedor, categoria RESTART IDENTITY CASCADE;

SELECT setval('categoria_id_seq', 10, true);





SELECT setval('factura_numero_seq', 301, false);


COMMIT;